  const originalLines = invoice.lines;

  addLine(invoice, { sku: 'STICKER', qty: 100 });

  assert.equal(invoice.lines.length, 1);
  assert.strictEqual(invoice.lines, originalLines);
  assert.equal(invoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(invoice.lines[0].qty, 5);
});

test('addLine enriches new line with catalogue data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });

