});

test('removeLine fails with NO_LINES if removing the last line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, name: 'Development (hour)', vatRate: 21 }],
  };

  const result = removeLine(invoice, 'DEV-HOUR');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('removeLine fails with NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, name: 'Development (hour)', vatRate: 21 },
      { sku: 'STICKER', qty: 100, unitPrice: 50, name: 'Sticker sheet', vatRate: 21 },
    ],
  };

  const result = removeLine(invoice, 'STICKER');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('removeLine does not mutate input invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, name: 'Development (hour)', vatRate: 21 },
      { sku: 'STICKER', qty: 100, unitPrice: 50, name: 'Sticker sheet', vatRate: 21 },
    ],
  };
  const originalLines = invoice.lines;

  removeLine(invoice, 'STICKER');

  assert.equal(invoice.lines.length, 2);
  assert.strictEqual(invoice.lines, originalLines);
  assert.equal(invoice.lines[1].sku, 'STICKER');
  assert.equal(invoice.lines[1].qty, 100);
});

test('removeLine on created invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'COPY-HOUR', qty: 2 },
      { sku: 'STICKER', qty: 50 },
    ],
  });

  assert.equal(result.ok, true);
  const removeResult = removeLine(result.value, 'COPY-HOUR');

  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 2);
  assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(removeResult.value.lines[1].sku, 'STICKER');
});

test('addLine and removeLine together', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });

  assert.equal(result.ok, true);

  const added = addLine(result.value, { sku: 'STICKER', qty: 100 });
  assert.equal(added.ok, true);
  assert.equal(added.value.lines.length, 2);

  const removed = removeLine(added.value, 'DEV-HOUR');
  assert.equal(removed.ok, true);
  assert.equal(removed.value.lines.length, 1);
  assert.equal(removed.value.lines[0].sku, 'STICKER');
});

