test('issueInvoice assigns number and changes status', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const issueResult = issueInvoice(result.value, []);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2026-0001');
  assert.equal(issueResult.value.status, 'issued');
  assert.equal(issueResult.value.customerId, 'C-001');
  assert.equal(issueResult.value.issueDate, '2026-10-07');
  assert.equal(issueResult.value.lines.length, 1);
});

test('issueInvoice uses existing numbers correctly', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const issueResult = issueInvoice(result.value, existing);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2026-0003');
});

test('issueInvoice handles different years', () => {
  const result2025 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result2026 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result2025.ok, true);
  assert.equal(result2026.ok, true);

  const existing = ['INV-2025-0001', 'INV-2026-0001'];

  const issue2025 = issueInvoice(result2025.value, existing);
  const issue2026 = issueInvoice(result2026.value, existing);

  assert.equal(issue2025.value.number, 'INV-2025-0002');
  assert.equal(issue2026.value.number, 'INV-2026-0002');
});

test('issueInvoice fails with NOT_DRAFT if already issued', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, name: 'Development (hour)', vatRate: 21 }],
  };

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('issueInvoice fails with NOT_DRAFT if status is other non-draft value', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, name: 'Development (hour)', vatRate: 21 }],
  };

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('issueInvoice does not mutate input invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  issueInvoice(invoice, ['INV-2026-0001']);

  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.number, undefined);
});

test('issueInvoice preserves invoice properties', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 50 },
    ],
  });

  assert.equal(result.ok, true);
  const issueResult = issueInvoice(result.value, []);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.customerId, 'C-003');
  assert.equal(issueResult.value.issueDate, '2026-10-07');
  assert.equal(issueResult.value.lines.length, 2);
  assert.equal(issueResult.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(issueResult.value.lines[0].name, 'Logo package');
  assert.equal(issueResult.value.lines[1].sku, 'STICKER');
});

